    miniAppsB1Desc: 'যখন কোনও অ্যাপ আপনাকে সাইন ইন করতে বলে, তখন এটি আপনার ওয়ালেটের ঠিকানা এবং একটি টোকেন পায় যা শুধুমাত্র সেই অ্যাপের জন্য কাজ করে । এটি কখনই আপনার ওয়ালেট, আপনার তহবিল বা আপনার DeHub অ্যাকাউন্টে অ্যাক্সেস পায় না ।',
