    miniAppsB3Desc: 'যে কোনও ওয়েবসাইট একটি স্ক্রিপ্ট ট্যাগ সহ একটি মিনি অ্যাপে পরিণত হয় । dehub.io/apps/dev আপনার স্পষ্টতা পরীক্ষা করে, আপনার ফিড কার্ডের পূর্বরূপ দেখে এবং অন্য কেউ এটি দেখার আগে DeHub-এর ভিতরে অ্যাপটি চালায় । Farcaster মিনি অ্যাপস যেভাবে কাজ করে ।',
