    superPowersDesc: 'সুপারপাওয়ার্স একটা স্টেকিং ব্যাড্জকে স্পেন্ড করা যেতে পারে এমন একটা রিচে রূপান্তর করে। প্রত্যেক ফোর্টনাইটে আপনার ব্যাড্জ বুস্টস দিতে থাকে, আর একটা স্পেন্ড করলে হোম ফিডের উপরে পোস্টের স্লটে একটা পোস্ট চলে যায়। টিম আপ একেবারে সবার জন্য খোলা এবং একসাথে সর্বোচ্চ আটটা ওয়ালেটের পাওয়ার কম্বাইন করে, ফলে প্রত্যেক সদস্য তাদের টোটাল আনলক করে বুঝতে পারে। স্লট ঘোরে: যখন একাধিক বুস্ট চলছে, তখন ভিউয়ারদের একটা বুস্ট দেওয়া হয়, যা বুঝতে হয় ব্যাড্জ টিয়ারের ওজন অনুযায়ী, তাই উচ্চ টিয়ারের বুস্ট বেশি দেখা যায় এবং সবাই তাদের দেওয়া উইন্ডো পায়।',
    superPowersDescV2: 'সুপারপাওয়ার্স একটা স্টেকিং ব্যাড্জকে স্পেন্ড করা যেতে পারে এমন একটা রিচে রূপান্তর করে। প্রত্যেক ফোর্টনাইটে আপনার ব্যাড্জ বুস্টস দিতে থাকে, আর একটা স্পেন্ড করলে হোম ফিডের উপরে পোস্টের স্লটে একটা পোস্ট চলে যায়। টিম আপ একেবারে সবার জন্য খোলা এবং একসাথে সর্বোচ্চ আটটা ওয়ালেটের পাওয়ার কম্বাইন করে, ফলে প্রত্যেক সদস্য তাদের টোটাল আনলক করে বুঝতে পারে। স্লট ঘোরে: যখন একাধিক বুস্ট চলছে, তখন ভিউয়ারদের একটা বুস্ট দেওয়া হয়, যা বুঝতে হয় ব্যাড্জ টিয়ারের ওজন অনুযায়ী, তাই উচ্চ টিয়ারের বুস্ট বেশি দেখা যায় এবং সবাই তাদের দেওয়া উইন্ডো পায়।',
