    feedsDesc2: 'ফিডের উপরে ট্যাবসহ বিভিন্ন ফরম্যাট দেখানো হয়। ডিফল্ট হোম ট্যাব তোমার ফলো করা লোকজন ও কমিউনিটির সবকিছু মিশিয়ে দেখায়; বিশেষ ট্যাবগুলো একক মিডিয়ামকে আলাদা করে রাখে, যেমন লং-ফর্ম ভিডিও বা শুধু সঙ্গীত ব্রাউজ করতে দিতে পারে। র‍্যাঙ্কিং প্ল্যাটফর্মের লিডারবোর্ড অ্যালগরিদম দ্বারা চালিত হয়, যা এই পেজের নিচে আরো বিস্তারিতভাবে বর্ণিত হয়েছে, তাই গুণগতমান ও এঙ্গেজমেন্ট, না বিজ্ঞাপনের খরচ, রিচ নির্ধারণ করে।',
