    feedsTranslateDesc: 'পোস্টস আৰু কমেন্টস আপনি স্ক্রোল করতেই আপনার ভাষাৰে অনুবাদ হৈ যাবে, একশতো ভাৰি ভাষাৰে, ওয়ালেট কানেকশন কোই নাই আৰু কোনো সেটিংস পাইও নাই। কোই কালে আপনি মূলটোৰে ফিরে যেতে পারিবেন।',
    communitiesTitle: 'সম্প্রদায় এবং ইভেন্ট',
    communitiesDesc: 'কমিউনিটি ডিহাব ভিতরে মেম্বার-রান স্পেস। প্রত্যেকটা নিজস্ব ফিড, মেম্বার লিস্ট, অ্যাক্টিভিটি স্ট্রিম আর নোটিফিকেশন চ্যানেল আছে, যাতে ক্রিয়েটর আর প্রোজেক্টস তাদের অডিয়েন্সের জন্য একটা ডেডিকেটেড হোম পায় প্ল্যাটফর্ম ছেড়ে না। কমিউনিটি হচ্ছে রিকারিং ইঙ্গেজমেন্টের জায়গা: মেম্বার পোস্ট করে, ডিসকাস করে, পোল রান করে আর একে-অপরের টিপ করে, আর আনরিড অ্যাক্টিভিটি নেভিগেশন বটমে ব্যাডজ হিসেবে দেখায় যাতে কেউই মিস করে না কি হচ্ছে।',
    communitiesB1: 'ব্রাউজ করো ও জুৱো:',
    stagesDesc: 'স্টেজ হৈল লাইভ অডিও রুম, টুইটার স্পেসের মতো, ডিহাব-এর ভিতরে সরাসরি বানাইয়া ফেলা। একটা হোস্ট রুম খুলে, স্পিকারকে স্টেজে আনা, আর কতোই লিসেনার হোক না কেন, স্টেজ পেজ বা শেয়ার করা ইনভাইট লিংক দিয়া তত্ক্ষণাতেই এনে বসতে পারিব। স্টেজ বানাইয়া হৈল বড়ো মাপের সত্যিকারের কথাবার্তা বলার জন্য: হোস্ট নিয়ন্ত্রণ করিব কে কে বলতে পারিব, লিসেনাররা লাইভ রিয়াকশন পাঠাইব, আর পুরো রুম রেকর্ড করা যাইব রিপ্লে করার জন্য।',
