    tvRadioDesc: 'বিয়ন্ড ক্রিয়েটর আপলোডস, ডিহাব কেয়া হোয়ে দেয় সবসময় চলে আছায় এন্টারটেইনমেন্ট সারফেসস, তো যেন আপনি অ্যাপ খুলে ফেললে দেখা বা শুনা কেয়া হোয়ে থাকে। এই লিন-ব্যাক এক্সপেরিয়েন্সস কেয়া হোয়ে চলে আছায়, আর ফ্লোটিং প্লেয়ারস দিয়ে আপনাকে পণ্য ভিতরে নেয়ে যাওয়ায়, তো মিডিয়া কেয়া হোয়ে থামে না যখন আপনি অন্য জায়গায় নেভিগেট করবেন।',
