    workDesc: 'বাউন্টি হান্টিং ডিহাবের ইনবিল্ট টাস্ক অ্যান্ড রিওয়ার্ড সিস্টেম, নন থার্ড-পার্টি ফ্রিল্যান্স মার্কেটপ্লেস। ইকোসিস্টেমের কেউই বাউন্টি পোস্ট করতে পারে, আর কেউই হান্টার হয়ে তা নিতে পারে, রিওয়ার্ড সেফলি রাখা থাকবে যতক্ষণ না কাজ ডেলিভার করা হয়। এটি কাজ এবং ইঙ্গেজমেন্টকে প্ল্যাটফর্মের নেটিভ পার্টে রূপান্তর করে: বাউন্টি পোস্ট করা লোকজন, কাজ সম্পন্ন করা হান্টার এবং তাদেরকে সেটল করার টোকেনস সবাই ডিহাবের ভিতরে থাকে। বাউন্টি ডিহাব টোকেন বা ইউএসডিসি দিয়ে পে করা হয়।',
    workDesc2: 'বাউন্টি হান্টিং কেননা এটি মাতৃভূমি, সারা ইকোসিস্টেমের জন্য একটি গ্রোথ ইঞ্জিন হিসেবে কাজ করে। ক্রিয়েটররা শেয়ার, ক্লিপ, রিকেশন বা তাদের কাজকে ছড়িয়ে দেওয়ার জন্য কন্টেন্ট পোস্ট করে বাউন্টি দিয়ে এনগেজমেন্ট বাড়ায় এবং তাদের কমিউনিটি তৈরি করে। প্রোজেক্টস এবং ডিহাব কমিউনিটির বড় অংশ বাউন্টি ব্যবহার করে নিজেদের প্রমোশন করে এবং ইকোসিস্টেম বাড়ায়, হান্টারদেরকে নতুন লোকদের আকর্ষণকারী টাস্কের জন্য পুরস্কার দেয়। একই সিস্টেম যা একটি কন্ট্রাক্ট সেটল করে, একইভাবে একটি কমিউনিটি এনগেজমেন্ট টাস্কও সেটল করে।',
    workB1Desc: 'কেউই একটা স্পষ্ট ব্রিফ দিয়ে আর ডিহাব টোকেন বা ইউএসডিসিয়ে একটা পুরস্কার ঘোষণা করে বাউন্টি পোস্ট করতে পারে, তাহলো কি একটা কাজ যা দিতে হবে অথবা একটা ইঙ্গেজমেন্ট টাস্ক যেমন কন্টেন্ট শেয়ার করা, ক্লিপ করা অথবা প্রমোট করা।',
    workB3Desc: 'বাউন্টিজ সোশ্যাল মিডিয়া, ক্লিপিং অ্যান্ড কন্ট্রাক্টস এ ভাগ করা হয়, তাই ইঙ্গেজমেন্ট টাস্কস অ্যান্ড লংগার পিসেস অফ ওয়ার্ক কে আলাদা আলাদা লেনে রাখা হয়।',
    workB6: 'বিতর্কসমূহ:',
