    aiSuiteDesc: 'DeHub মাৰে একটা পূর্ণাঙ্গ সেট AI টুলস কৰা হৈছে কৰ্তাৰ পৰা, সাবলম্বিত হৈছে অ্যাপ ভিতৰে, কোনো বাইৰি অ্যাকাউন্ট অথবা API কি নাই। এই স্যুট মাৰে একটা চ্যাটিং এসিস্ট্যান্ট, স্বয়ংক্রিয় এজেন্ট, আর নো-কোড অ্যাপ বিল্ডার পৰা হৈছে, তাই তুমি একটা আইডিয়াৰ পৰা জেনেৰেটেড কন্টেন্ট অথবা একটা কাজকাৰী মিনি-অ্যাপ বানাই পাৰো, প্লাটফর্ম ছাড়া কোথাও যাই নাই।',
    aiSuiteB5Desc: '@assistant মেনশন ক’রে পোস্ট, কমেন্ট থ্রেড অথবা লাইভ চ্যাটে লিখলে সে সঠিক প্ল্যাটফর্ম টুলস ব্যবহার করে সেখানে উত্তর দিবে, না কি কীওয়ার্ড ম্যাচিং। তোই এছাড়াও একটা মানবসহায়তা টিকিটও ফাইল করিবে।',
