    notificationsTitle: 'আপনার পোস্ট প্রকাশ হয়েছে',
    appsDesc: 'DeHub কে কোথাওই চালানো যায়। dehub.io তে থাকা ওয়েব অ্যাপটি ব্রাউজারে পুরো প্রোডাক্ট এবং ডেস্কটপ ও ফোন উভয়েই হোম স্ক্রিনে ইনস্টল হয়ে একটি নেটিভ অ্যাপের মতো কাজ করে। অ্যান্ড্রয়েড অ্যাপটি গুগল প্লেতে আছে, এবং সর্বশেষ বিল্ডটি সবাইকে স্টোর ছাড়াই সরাসরি dehub.io/apk থেকে ডাউনলোড করতে পাওয়া যায়। ফিড, স্টেজ, পোস্টিং, মেসেজিং, ওয়ালেট এবং নোটিফিকেশন উভয় প্ল্যাটফর্মেই একইভাবে কাজ করে, এবং আপনার অ্যাকাউন্ট, ব্যাডজ এবং ব্যালেন্স তাদের মধ্যে আপনাকে অনুসরণ করে।',
