    profileB4: 'প্লেলিস্টস:',
    dpayDesc: 'DeHub Pay: কার্ড দিয়া Stripe মাদ্দেমে কিন, অথবা অন্য চেইন দিয়া ক্রিপ্টো দিয়া, $০.৫০ দিয়া থেকেই।',
    tipDesc3: 'টিপস পোস্ট, কমেন্ট, ডিরেক্ট মেসেজ এবং লাইভ স্ট্রিমে কাজ করে। যদি আপনার ডিহাব টোকেন কম থাকে, তাহলে টিপ শীট আপনার অন্যান্য ব্যালেন্স — ইউএসডিসি, ইথি, বা বেস, বিএনবি চেইন, রবিনহুড চেইন বা আর্কে থাকা টোকেনগুলো দেখাবে এবং টিপ যাওয়ার আগে তা আপনার জন্য রূপান্তর করবে। একবার আপনি কোনো পোস্ট টিপ দিলে, তার টিপ বাটনে একটি চমকপ্রদ ডায়মন্ড দেখাবে যাতে আপনি দেখতে পারবেন যে আপনি ইতিমধ্যে কোথায় টিপ দিয়েছেন।',
