    profileB7: 'আপনার অবতরণ পাতা:',
    profileB7Desc: 'আপনার প্রোফাইল খুললে ভিজিটররা কোন ট্যাবে পৌঁছাবে তা নির্বাচন করুন। হেডার স্ক্রোল করার সাথে সাথে একটি ফ্রোস্টেড বারে পরিণত হয়, প্রতিটি ট্যাব তার সম্পূর্ণ মূল্য দেখায় এবং আপনি সেটিংস থেকে আপনার নামটি পরিবর্তন করতে পারেন।',
    profileB8: 'পিন্ড কমিউনিটি আর্ট:',
    profileB8Desc: 'আপনার প্রোফাইলে একটা কমিউনিটি পিন করেন আর ডেস্কটপে, প্রোফাইলটা সেই কমিউনিটির আর্টওয়ার্ক ধরি নেয়।',
    topUpTitle: '২ ক্লিকে টোকেন টপ আপ করেন',
    topUpShotAlt: 'অ্যাপের ভেতর থাকি সরাসরি DeHub টোকেন কেনা যায়।',
    topUpDesc: 'আমাদের নিজস্ব ইন-অ্যাপ কারেন্সি আছে, যেমনটা আপনারা ফোর্টনাইট (Fortnite) বা টিকটক (TikTok) কয়েন পান, আমাদেরটা হলো DeHub টোকেন। অ্যাপের সব জায়গায় আপনারা এইগুলা সোনার কয়েন হিসেবে দেখবেন। এইগুলা প্রিমিয়াম সার্ভিস যেমন টিপস, সাবস্ক্রিপশন আর আরও অনেক কিছুর জন্য ব্যবহার করা হয়। ব্রাউজিং ফ্রি, আর প্রতিদিনের লিমিটের ভেতর পোস্ট করাও ফ্রি—যদি আপনারা সোশ্যাল মিডিয়া, ইমেইল বা এসএমএস দিয়া সাইন আপ করেন, তবে আমরা আপনার সব গ্যাস ফি দিয়া দিমু। ওয়ালেট ব্যবহারকারীরা স্ট্যান্ডার্ড ETH বা BNB গ্যাস ফি দিবেন। নিচে ২ ক্লিকে টোকেন টপ আপ করেন।',
    directTitle: 'সরাসরি',
    topUpCardDesc: 'কেনার পেজটা DeHub Pay দিয়া চলে। কার্ড দিয়া পেমেন্ট করেন, অথবা অন্য চেইনে থাকা ক্রিপ্টো দিয়া পেমেন্ট করেন, সেইটা আপনার জন্য কনভার্ট হইয়া যাবে। সর্বনিম্ন $০.৫০। ETH আর USDC কার্ড দিয়া MoonPay-এর মাধ্যমেও কেনা যায়, যেই চেইনে আপনি আছেন সেই চেইনতেই, আর সেইটা সরাসরি আপনার অ্যাপের ওয়ালেটে জমা হইয়া যাবে। একবার কেনা শেষ হইলে আপনি এক ট্যাপেই সেইটা ফিডে শেয়ার করতে পারবেন।',
