    boostPower: '১) বুস্ট',
    boostPowerDesc: 'পূর্বের সপ্তাহের একটি পোস্টকে হোম ফিডের শীর্ষে রাখুন। উন্মোচন করুন ক্র্যাব লাইভ এখন।',
    secondWindPower: '২) সেকেন্ড ওয়াইন্ড',
