    trendJackerDesc2: 'তোমার ক্যাটাগরিগুলার একটা ট্রেন্ডিং লিস্টের উপরে রাখো। জায়ান্ট টরটয়েজ (Giant Tortoise)-ত আনলক হয়। এ্যালা লাইভ।',
    precisionStrike: '৮) প্রিসিশন স্ট্রাইক (Precision Strike)',
    precisionStrikeDesc: 'তুমি যে একাউন্টের নাম কইবা, সেই একাউন্টের ফলোয়ারগুলার কাছে পৌঁছাও। ডলফিন (Dolphin)-ত আনলক হয়। এ্যালা লাইভ।',
    harpoonDesc: 'তোমার পছন্দ করা ব্যাজ টায়ারের সব হোল্ডারক একটা পোস্টের ব্যাপারে নোটিফাই করো। টাইগার শার্ক (Tiger Shark)-ত আনলক হয়। এ্যালা লাইভ।',
    superPowersMore2: 'বারোটা পাওয়ারই লাইভ আছে আর অ্যাপোত লিস্ট করা আছে। কমেন্ট এঙ্কর (Comment Anchor) অন্য কারো থ্রেডের উপরে তোমার কমেন্ট ধইরা রাখে। সিগন্যাল ফ্লেয়ার (Signal Flare) তোমাকে ফলো করা সব একাউন্টের কাছে একটা নোটিফিকেশন পাঠায়। ফ্ল্যাক জ্যাকেট (Flak Jacket) একটা পোস্টক ডাউনভোটের হাত থাকি বাঁচায় যতক্ষণ এটা চলে। টিম আপ (Team up) আটটা পর্যন্ত একাউন্টক তাদের ওয়ালেট পাওয়ার এক করার সুযোগ দেয়, যাতে সব মেম্বার তাদের পুল করা ব্যালেন্সের ব্যাজটা পায়। ফ্রন্ট রো (Front Row) তোমার হোস্ট করা স্টেজক স্টেজ রেইলের উপরে রাখে। ডিপ কারেন্ট (Deep Current) তোমার একটা বুস্ট অন্য কারো পোস্টত দেয়।',
    superPowersMoreV2: 'বারোটা পাওয়ারই লাইভ আছে আর অ্যাপোত লিস্ট করা আছে। কমেন্ট এঙ্কর (Comment Anchor) অন্য কারো থ্রেডের উপরে তোমার কমেন্ট ধইরা রাখে। সিগন্যাল ফ্লেয়ার (Signal Flare) তোমাকে ফলো করা সব একাউন্টের কাছে একটা নোটিফিকেশন পাঠায়। ফ্ল্যাক জ্যাকেট (Flak Jacket) একটা পোস্টক ডাউনভোটের হাত থাকি বাঁচায় যতক্ষণ এটা চলে। টিম আপ (Team up) আটটা পর্যন্ত একাউন্টক তাদের ওয়ালেট পাওয়ার এক করার সুযোগ দেয়, যাতে সব মেম্বার তাদের পুল করা ব্যালেন্সের ব্যাজটা পায়। ফ্রন্ট রো (Front Row) তোমার হোস্ট করা স্টেজক স্টেজ রেইলের উপরে রাখে। ডিপ কারেন্ট (Deep Current) তোমার একটা বুস্ট অন্য কারো পোস্টত দেয়।',
