    spNameTimelineBomber: 'টাইমলাইন বম্বার (Timeline Bomber)',
    spDescSignalFlare: 'তোমার ফলোয়ারগুলার কাছে একটা পোস্টের ব্যাপারে একটা নোটিফিকেশন। এইটা আলাদা সিগন্যাল এলাউন্স থাকি খরচ হয়, তোমার বুস্ট থাকি না।',
