    disclaimerText: 'দেহাব টোকেনসমূহ কেবলমাত্র কার্যকরী উদ্দেশ্যে ব্যবহৃত হয়, যেন কোনো গেম বা অ্যাপের ডিজিটাল টোকেন বা মুদ্রা। কারণ আমাদের টোকেন চেইনে থাকে, তাই আমরা অতিরিক্ত কার্যকারিতা এবং অপরিসীম পরিমাণে যাচাইযোগ্য স্বচ্ছতা প্রদান করতে পারি। উপরের ডেটা সম্পূর্ণরূপে স্বচ্ছতা, শিক্ষামূলক এবং তথ্যপূর্ণ উদ্দেশ্যে সংকলিত হয়েছে। দেহাব এবং এর সমস্ত সহযোগী সংস্থাগুলো কোনো টোকেন বা এনএফটি ক্রয় থেকে হওয়া অর্থনৈতিক ক্ষতির জন্য কোনো দায়িত্ব বহন করে না। বাজার অত্যন্ত অস্থির। আপনি অপ্রত্যাশিত ত্রুটিসমূহ যেমন দক্ষতা ব্যর্থতা, প্রযুক্তিগত ত্রুটি, হ্যাকিং ইত্যাদি কারণে সকল অর্থ হারাতে পারেন। তাই আপনি কেবলমাত্র যে পরিমাণ অর্থ হারাতে পারবেন সেই পরিমাণ অর্থই ব্যয় করুন।',
