    howItWorksDesc2: 'এই পথে সমস্ত ইকোসিস্টেমের উপকার হয়, না কেবল একক কোনো দলের। কন্টেন্ট ক্রিয়েটর, কনসিউমার, হোল্ডার ও প্ল্যাটফর্মে বিজ্ঞাপন দিচ্ছে এমন কোম্পানিগুলো সবাই বেশি পুরস্কার পায়।',
    howItWorksDesc3: 'ফাইন্যান্সিয়াল ডেটা হৈত সবচেয়ে লাভজনক, আর আমাদের ডেটা একক সিস্টেমে একত্রিত হৈছে যেটা অ্যাডভারটাইজারগণ লক্ষ্যবস্তুকে টার্গেট করিবার জন্য ব্যবহার কৰিব পায়। এইটা এমন কিছু নাই যেটা অফ-চেইনে কৰা যাইত, কেননা ব্যাংক স্টেটমেন্ট গুলো প্রাইভেট হৈত আর ব্লকচেইন পাবলিক হৈত।',
    howItWorksDesc4: 'মহা-বড় ব্যবসায়ীদের ও বড়-বড় খরচকারী লোকদের লক্ষ্য করে কাজ করা, আর ছোট-ছোট ব্যবসায়ীদের ও সাধারণ লোকদের জন্য বিশেষ অফার বা ছাড় দিতে পারা—এই ধরনের বিজ্ঞাপন পদ্ধতি বিশ্বব্যাপী বিজ্ঞাপনের রূপান্তর করবে। কেন কেউ এইটা চাইবে না?',
    preventFraudDesc1: 'বটিংয়ের লাভ কমে যাচ্ছে যখন অ্যাক্টিভিটি চেইনে ট্র্যাক করা যায়, খুব সহজেই মন্দ অ্যাক্টরদের সংযোগ করা যায় এবং শেষ পর্যন্ত পুরো ইউজার বেস কুরেট করা যায়। বিজ্ঞাপনদাতারা উচ্চ র‍্যাংকযুক্ত ইউজারদের লক্ষ্য করে, যার ফলে নিচের স্তরে খুব কমই এক্সট্রাক্টেবল ভ্যালু থাকে, যেখানে যে কোনো অবশিষ্ট ফরড মাত্রই থাকে। এছাড়াও, আমাদের ডিসেন্ট্রালাইজড মডারেশন ইলিসিট অ্যাক্টিভিটির আরও কার্যকরভাবে ডিটেকশন এবং প্রিভেনশন করতে সাহায্য করে।',
