    welcomeText: 'ধন্যবাদ DeHub প্লাটফর্ম ব্যবহার করার জন্য এবং তোমাকে যে সকল পণ্য, সেবা ও বৈশিষ্ট্য আমরা তোমার জন্য প্লাটফর্মের অংশ হিসেবে প্রদান করি (সকলকেই একত্রে "সেবা" বলা হয়েছে)।',
    ourServiceText2: 'DeHub কা অপারেটিং হৈতো একটা ডিসেন্ট্রালাইজড প্রোটোকল, জহাঁ কন্টেন্ট মডারেশন হৈতো কমিউনিটি গভর্নেন্স বাই হাত, তক্কা শুধু আইলিগাল কন্টেন্ট অথবা কমিউনিটি-অপ্রুভড গাইডলাইনস ভাঙা কন্টেন্ট মাত্র রেস্ট্রিক্ট হৈসকা পারিবে।',
    softwareDevText1: 'DeHub একটা স্বাধীন DAO. কোন কোম্পানি এই সার্ভিসটিকে মালিকানা রাখে, পরিচালনা করে বা নিয়ন্ত্রণ করে না। প্রোটোকল, প্লাটফর্ম এবং ট্রেজারি সকলেই DeHub টোকেনধারকদের দ্বারা DeHub গভর্নেন্স প্রোটোকলের মাধ্যমে চেইনে পরিচালিত হয়, যা বর্তমানে লাইভ আছে। প্রস্তাবগুলো অ্যাপে উত্থাপিত হয় এবং ভোট দেওয়া হয়, এবং ফলাফলটি ইকোসিস্টেমকে বাঁধা দেয়। এই চুক্তিতে "DeHub", "আমরা", "আমরা" এবং "আমাদের" শব্দগুলো DAO এবং তার নিয়ন্ত্রণ করা প্রোটোকলকে বোঝায়, কোন কোম্পানিকে নয়।',
    parentPermissionText: 'তুমি যদি ১৮ বছরের নিচে হো, তাহলে তোমার পিতামাতা বা আইনি অভিভাবকের অনুমতি ছাড়া এই সেবা ব্যবহার করা যাবে না। তাদেরকে এই চুক্তি তোমার সাথে পড়তে বলো।',
    businessesText: 'তুমি কোনো কোম্পানি বা সংস্থার পক্ষে এই সেবা ব্যবহার করছো তাহলে তুমি আমাদেরকে নিশ্চিত করো যে তুমি সেই সংস্থার পক্ষে কাজ করার অনুমতি পেয়েছো, আর সেই সংস্থা এই চুক্তি মেনে নেয়।',
    walletText1: 'তুমি কোনো ওয়ালেট কানেক্ট কৰে বিনা পৰবতত, যেমন কন্টেন্ট ব্রাউজ কৰে আৰু ডিসকভার কৰে, এই সেবাৰ অংশ ব্যবহার কৰতে পারো। কিন্তু মুনিটাইজেশন ফিচার ব্যবহার কৰে আৰু গভর্নেন্স মে অংশ নেওয়াৰ পৰে তুমি একটা কোম্প্যাটিবল ক্রিপ্টো ওয়ালেট কানেক্ট কৰতে হবে।',
    tokenUsageItem3: 'প্রিমিয়াম কন্টেন্ট আনলক করুন',
    tokenUsageItem4: 'সুপার পাওয়ারস অ্যাক্সেস করা যেমন ট্রেন্ডিং বুস্টস',
    purchaseLimitsText: 'মাক্সিমাম দৈনিক ব্যাংক কার্ড দিয়া কেনার সীমা হৈছে $৫০০ মার্কিন ডলার সমান। এই সীমা নিরাপত্তা আর নিয়মকানুন মেনে চলার জন্য রাখা হৈছে।',
    refundsPolicyText: 'ব্লকচেইন ট্রানজেকশনের অপরিবর্তনীয় প্রকৃতির কারণে, যদি বিক্রয় বর্ণিত মতো না হয় অথবা যা করা উচিত তার মতো কাজ না করে, তাহলে শুধুমাত্র তখনই রিফান্ড করা যাবে। সব টোকেন কেনার ট্রানজেকশন ফাইনাল এবং রিভার্স, ক্যান্সেল বা রিফান্ড করা যাবে না, যতক্ষণ না উপরের শর্তগুলো ভঙ্গ হয়।',
    fiatOnRamp: 'ফিয়াট অন-র্যাম্প সার্ভিসেস',
