    monetizationText: 'অনেকটা ঐতিহ্যবাহী প্ল্যাটফর্মের মতো নহে, ডিহাব সকল ব্যবহারকারীদের জন্য অপরিবর্তিত আয়ের অধিকার প্রদান করে, শুধু এই শর্তে যে—',
