    designatedModeratorsItem1: 'নির্দিষ্ট মোডারেটররা কোনো পোস্ট, কমেন্ট, স্ট্রিম বা মিডিয়া আইটেমকে তৎক্ষণাত সরিয়ে ফেলতে পারে।',
