    doCollectItem1: 'তোমার লগইন কা ইডেন্টিফায়ার — যদি তুমি ইমেইল অথবা ফোন নম্বর বাছো, তাহা তোমার ইমেইল অথবা ফোন নম্বর হব; সোশ্যাল লগইন কা মানে গুগল, অ্যাপল অথবা টেলিগ্রাম কা রিটার্ন কা আইডেন্টিটি; অথবা একটা পাসকি কা পাবলিক ক্রেডেনশিয়াল। ওয়ালেট লগইন মানে আমাদের তোমার পাবলিক অ্যাড্রেস মাত্র দিবে।',
