    a12: 'DeHub একটি সাবধানে ডিজাইন করা টোকেনমিক্স মডেল অনুসরণ করে। বিস্তারিত তথ্যের জন্য আমাদের টোকেন ইকোনমিক্স বিভাগ দেখুন।',
    a13: 'টোকেনধারীরা গভর্নেন্স পৃষ্ঠা থেকে অংশ নেন: তাদের থ্রেডেড মন্তব্যগুলিতে প্রস্তাবগুলি পড়ুন এবং আলোচনা করুন, আপনার ব্যাজ দ্বারা নির্ধারিত ওজনের সাথে বিনামূল্যে বা বিপক্ষে ভোট দিন, বা 10,000-টোকেন ফি এর জন্য আপনার নিজের একটি প্রস্তাব খুলুন । DAO ট্রেজারি পৃষ্ঠাটি যে কাউকে ডিহাব টোকেনগুলিতে অবদান রাখতে এবং সেই ট্রেজারি কীভাবে ব্যয় করা হয় তার অনুপাতে ভোট দিতে দেয় ।',
    a15: 'হ্যাঁ, আপনি DeHub টোকেন ব্যবহার করে প্রকাশিত বা টোকেন-লক করা সামগ্রীতে বাউন্টি সংযুক্ত করে নির্মাতাদের এবং দর্শকদের পুরস্কৃত করতে পারেন ।',
    a7: 'ছয়টি গেম ডিহাবের ভিতরে চলে, একটি ব্রাউজার ট্যাবে, ইনস্টল করার কিছুই নেই এবং কেনার কিছুই নেই: কিংস গ্যাম্বিট (একটি অনলাইন এলো মই সহ 3 ডি দাবা), ক্লাউড অফ ডিউটি (একটি শ্যুটার যা আপনার মেশিনে নিজস্ব সমস্ত শিল্প তৈরি করে), জঙ্গল ট্রিল (একটি পদ্ধতিগতভাবে উত্পন্ন রেইনফরেস্ট ওয়াক আপ), স্ট্রিট স্লেয়ার (একটি সাইড স্ক্রোলিং বীট \'এম আপ ডেহাবের জন্য নির্মিত), চার্টোপিয়া (একটি হাঁটাযোগ্য ট্রেডিং ফ্লোর যা একটি ভিআর হেডসেটেও চলে) এবং ঈশ্বরের চোখ (ডিএইচইউবি সম্প্রদায়ের একটি লাইভ 3 ডি গ্লোব) । লাস্ট চাদ স্ট্যান্ডিং, আমাদের ফ্ল্যাগশিপ এমএমএ ব্যাটল রয়্যাল, বিকাশে রয়েছে ।',
    commonQuestions: 'সাধারণ প্রশ্ন',
