    useTippingDesc: 'একটি পোস্ট, সংক্ষিপ্ত, স্ট্রিম বা মঞ্চে সরাসরি কোনও সৃষ্টিকর্তার কাছে মান পাঠান — অবিলম্বে, বিশ্বব্যাপী এবং কোনও মধ্যস্থতাকারী ছাড়াই স্থানান্তরটি এড়িয়ে যান ।',
