    useCasesTitle: 'এটা কি কেয়া কাজে লাগে?',
    useRewardsDesc: 'x-2-earn পে-আউটস, র‍্যাওয়ার্ডস দেখা, প্রকাশিত কন্টেন্টে বাউন্টিস, র‍্যাফলস, গেমস এবং কমিউনিটি ক্যাম্পেইনস সবাই ডি-হাব টোকেনে ডেনোমিনেটেড এবং পে করা হয়।',
    useCommerceTitle: 'দোকান ও মার্কেটপ্লেস',
    useCommerceDesc: 'কিনুন প্ৰোডাক্ট, ডিজিটাল কালেক্টেবল, সেবা আর ফিগিটাল এনএফটি ক্ৰিয়েটর স্টোর আর মার্কেটপ্লেস থেকে একটা একাউন্টে প্ৰয়োজনীয়তা অনুযায়ী।',
    useFeesDesc: 'পে নেটওয়ার্ক ফি, ক্লাব টিয়ার্স মাঝে স্টেক করো ফর প্রোটোকল রেভিনিউ শেয়ার, আর ডিহাব টোকেনস জালিয়ে গভর্নেন্স ভোট দিতে প্রোটোকল ডিসিশনস মাঝে।',
    profitShareTitle: 'লাভ ভাগা',
    profitShareDesc1: 'DeHub কে এতরকম ডিজাইন করা হৈছে যেন নেটওয়ার্ক ব্যবহার কৰণ কৰণে লোকজন তোই নেটওয়ার্ক কে মালিক বানাইব। প্রোটোকল রেভিনিউ — প্লাটফর্ম ফি, স্টোর এবং মার্কেটপ্লেস ফি, বিজ্ঞাপন, এআই ব্যবহার এবং গেম রেভিনিউ — স্টেক কৰণে হোল্ডারগণকে ফিরাইব, রিয়েল-ইয়িল্ড ডিস্ট্রিবিউশন এবং ব্যাক-বাই কে আকারে, নবীন মিন্টেড সাপ্লাই নহে। তাই DeHub টোকেন মালিকবানাইবা নেটওয়ার্ক কে কে আংশিক মালিকবানাইবা, নহে কেবলমাত্র খরচ কৰণে ব্যালেন্স মাত্র।',
    pegTitle: 'পেগড প্রাইস অ্যান্ড ডিক্স লিস্টিং',
    pegDesc1: 'দেহাব টোকেন একটা ইউটিলিটি টোকেন। অ্যাপ ভিতরে ব্যবহার করার জন্য বর্তমানে প্রতি টোকেনের মূল্য $০.০০১ এ পেগ করা আছে, যা ফিয়াট গেটওয়ে দিয়ে কিনতে দেখতে পাওয়া মূল্য এবং অ্যাপ ভিতরে মূল্য নির্ধারণে ব্যবহৃত হয়। এই পেগিং অ্যাপ ভিতরের অর্থনীতিকে স্থিতিশীল ও পূর্বাভাসযোগ্য রাখার জন্য করা হয়েছে যখন নেটওয়ার্ক স্কেল করা হচ্ছে — এটি একটা অভ্যন্তরীণ হিসাবরক্ষণ হার, নিচের সীমা, গ্যারান্টি বা ভবিষ্যতের মূল্যের প্রতিশ্রুতি নয়।',
    pegDesc2: 'ডেক্সে টোকেন ট্রেড হৈছে, যেখানে লিকুইডিটি পুলहरूको स्रोत त्यही ০.০০१ बेस प्राइसबाट विभिन्न चेनहरूमा बाँडिएको छ। ओपन मार्केटमा प्राइस ट्रेडिङ् बाट निर्धारित हुन्छ—न डिहबबाट—जसले अर्थात् डिहब टोकनहरू इन-एप पिगबाट माथि वा तलको मूल्यमा ट्रेड हुन सक्छन्। डिहबले आफ्नो आधिकारिक लिकुइडिटी डेक्सहरूमा सिड हुन्छ जसले गर्दा प्रत्येक ट्रान्जेक्शन चेनमा सार्वजनिक रूपमा वेरिफाई हुनेछ।',
    disclaimerText: 'দেহাব টোকেনসমূহ কেবলমাত্র কার্যকরী উদ্দেশ্যে ব্যবহৃত হয়, যেন কোনো গেম বা অ্যাপের ডিজিটাল টোকেন বা মুদ্রা। কারণ আমাদের টোকেন চেইনে থাকে, তাই আমরা অতিরিক্ত কার্যকারিতা এবং অপরিসীম পরিমাণে যাচাইযোগ্য স্বচ্ছতা প্রদান করতে পারি। উপরের ডেটা সম্পূর্ণরূপে স্বচ্ছতা, শিক্ষামূলক এবং তথ্যপূর্ণ উদ্দেশ্যে সংকলিত হয়েছে। দেহাব এবং এর সমস্ত সহযোগী সংস্থাগুলো কোনো টোকেন বা এনএফটি ক্রয় থেকে হওয়া অর্থনৈতিক ক্ষতির জন্য কোনো দায়িত্ব বহন করে না। বাজার অত্যন্ত অস্থির। আপনি অপ্রত্যাশিত ত্রুটিসমূহ যেমন দক্ষতা ব্যর্থতা, প্রযুক্তিগত ত্রুটি, হ্যাকিং ইত্যাদি কারণে সকল অর্থ হারাতে পারেন। তাই আপনি কেবলমাত্র যে পরিমাণ অর্থ হারাতে পারবেন সেই পরিমাণ অর্থই ব্যয় করুন।',
